// evosim showcase — gallery + detail dialog, driven by window.SIMS
// (generated by scripts/export_showcase.py into frontend/data/sims.js).
// Implements design-system handoff: filter chips, before/after treatment,
// per-slug hash URLs, keyboard-safe dialog with prev/next navigation.

const SIMS = window.SIMS || [];
const gallery = document.getElementById("gallery");
const filtersNav = document.getElementById("filters");
const dialog = document.getElementById("detail");
const video = dialog.querySelector(".detail-video");

const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
const canHover = matchMedia("(hover: hover)").matches;

let activeFilter = "all";
let currentIndex = -1;

const isUntrained = (sim) => sim.policy.toLowerCase().startsWith("random");
const filtered = () =>
  SIMS.filter((s) => activeFilter === "all" || s.kind === activeFilter);

/* ---------- filter chips ---------- */

function renderFilters() {
  const kinds = ["all", ...new Set(SIMS.map((s) => s.kind))];
  filtersNav.replaceChildren(
    ...kinds.map((kind) => {
      const count =
        kind === "all" ? SIMS.length : SIMS.filter((s) => s.kind === kind).length;
      const chip = document.createElement("button");
      chip.className = "chip";
      chip.textContent = `${kind} · ${count}`;
      chip.setAttribute("aria-pressed", String(kind === activeFilter));
      chip.addEventListener("click", () => {
        activeFilter = kind;
        renderFilters();
        renderGallery();
      });
      return chip;
    })
  );
}

/* ---------- gallery cards ---------- */

function policyLabel(sim) {
  return isUntrained(sim) ? "RANDOM" : sim.policy;
}

function card(sim) {
  const el = document.createElement("article");
  el.className = "card" + (isUntrained(sim) ? " before" : "");
  el.tabIndex = 0;
  el.setAttribute("role", "button");
  el.setAttribute("aria-label", `${sim.id} — ${sim.kind}, policy ${policyLabel(sim)}, mean return ${sim.meanReturn}`);
  el.innerHTML = `
    ${isUntrained(sim) ? '<span class="before-tag">BEFORE</span>' : ""}
    <video src="${sim.video}" muted loop playsinline preload="metadata"></video>
    <div class="card-body">
      <h3 class="card-title">${sim.id}
        <span class="kind" data-kind="${sim.kind}"><span class="dot"></span>${sim.kind}</span>
      </h3>
      <div class="card-foot">
        <span class="policy">${policyLabel(sim)}</span>
        <span class="mu">&mu; ${sim.meanReturn}</span>
      </div>
    </div>`;

  const v = el.querySelector("video");
  if (!reducedMotion && canHover) {
    el.addEventListener("mouseenter", () => v.play());
    el.addEventListener("mouseleave", () => v.pause());
  }
  const open = () => openDetail(sim);
  el.addEventListener("click", open);
  el.addEventListener("keydown", (e) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      open();
    }
  });
  return el;
}

/* On touch devices there is no hover — autoplay cards while in view. */
let observer = null;
function observeCards() {
  if (observer) observer.disconnect();
  if (reducedMotion || canHover) return;
  observer = new IntersectionObserver(
    (entries) =>
      entries.forEach((e) => (e.isIntersecting ? e.target.play() : e.target.pause())),
    { threshold: 0.4 }
  );
  gallery.querySelectorAll("video").forEach((v) => observer.observe(v));
}

function renderGallery() {
  gallery.replaceChildren(...filtered().map(card));
  observeCards();
}

/* ---------- detail dialog ---------- */

function fmtTime(t) {
  if (!isFinite(t)) return "00:00";
  const m = String(Math.floor(t / 60)).padStart(2, "0");
  const s = String(Math.floor(t % 60)).padStart(2, "0");
  return `${m}:${s}`;
}

function openDetail(sim) {
  currentIndex = filtered().indexOf(sim);

  dialog.classList.toggle("untrained", isUntrained(sim));
  video.src = sim.video;
  dialog.querySelector(".kind-label").textContent = sim.kind;
  dialog.querySelector(".detail-kind .dot").style.background =
    getComputedStyle(document.documentElement).getPropertyValue(
      sim.kind === "locomotion" ? "--accent" : sim.kind === "manipulation" ? "--accent-2" : "--untrained"
    );
  dialog.querySelector(".detail-kind").style.color =
    dialog.querySelector(".detail-kind .dot").style.background;
  dialog.querySelector(".detail-title").textContent = sim.id;
  dialog.querySelector(".detail-desc").textContent = sim.description;
  dialog.querySelector(".stat-policy").textContent = sim.policy;
  dialog.querySelector(".stat-return").textContent = sim.meanReturn;
  dialog.querySelector(".stat-episodes").textContent = sim.evalEpisodes;
  dialog.querySelector(".detail-cmd").textContent =
    `$ python scripts/export_showcase.py --env ${sim.id}`;

  if (!dialog.open) dialog.showModal();
  history.replaceState(null, "", `#/sims/${sim.slug}`);
  if (!reducedMotion) video.play();
}

function stepDetail(delta) {
  const list = filtered();
  if (!list.length) return;
  const next = list[(currentIndex + delta + list.length) % list.length];
  openDetail(next);
}

video.addEventListener("timeupdate", () => {
  const pct = video.duration ? (video.currentTime / video.duration) * 100 : 0;
  dialog.querySelector(".progress-fill").style.width = `${pct}%`;
  dialog.querySelector(".media-meta").textContent =
    `${fmtTime(video.currentTime)} / ${fmtTime(video.duration)} · muted · loop`;
});

dialog.querySelector(".detail-close").addEventListener("click", () => dialog.close());
dialog.addEventListener("click", (e) => {
  if (e.target === dialog) dialog.close();
});
dialog.addEventListener("keydown", (e) => {
  if (e.key === "ArrowRight") stepDetail(1);
  if (e.key === "ArrowLeft") stepDetail(-1);
});
dialog.addEventListener("close", () => {
  video.pause();
  history.replaceState(null, "", location.pathname);
});

/* ---------- boot ---------- */

renderFilters();
renderGallery();

const initial = SIMS.find((s) => location.hash === `#/sims/${s.slug}`);
if (initial) openDetail(initial);
